INSERT OR REPLACE INTO ai_lesson_exercises (id, lesson_id, sync_code, model, total_exercises, exercises_data, created_at, updated_at) VALUES ('minna_2_global', 'minna_2', 'global', 'curated-minna-i', 47, '[{"id":"cloze_minna_2_0","vocabId":"minna_2_0","targetWord":"これ","targetReading":"これ","sentence":"（　　）は辞書です。日本語の辞書です。","fullSentence":"これは辞書です。日本語の辞書です。","translation":"Đây là cuốn từ điển. Là từ điển tiếng Nhật.","options":["これ","それ","あれ","どれ"],"correctIndex":0,"explanation":"「これ」 chỉ vật ở gần người nói (cái này, đây)."},{"id":"cloze_minna_2_1","vocabId":"minna_2_1","targetWord":"それ","targetReading":"それ","sentence":"（　　）は傘ですか。…はい、そうです。","fullSentence":"それは傘ですか。…はい、そうです。","translation":"Đó có phải là cái ô không? ...Vâng, đúng vậy.","options":["これ","それ","あれ","だれ"],"correctIndex":1,"explanation":"「それ」 chỉ vật ở gần người nghe (cái đó, đó)."},{"id":"cloze_minna_2_2","vocabId":"minna_2_2","targetWord":"あれ","targetReading":"あれ","sentence":"（　　）は病院です。あそこに見えます。","fullSentence":"あれは病院です。あそこに見えます。","translation":"Kia là bệnh viện. Có thể thấy ở đằng kia.","options":["これ","それ","あれ","この"],"correctIndex":2,"explanation":"「あれ」 chỉ vật ở xa cả người nói và người nghe (cái kia, kia)."},{"id":"cloze_minna_2_3","vocabId":"minna_2_3","targetWord":"この","targetReading":"この~","sentence":"（　　）本はわたしのです。","fullSentence":"この本はわたしのです。","translation":"Cuốn sách này là của tôi.","options":["この","その","あの","どの"],"correctIndex":0,"explanation":"「この」 đứng trước danh từ để chỉ vật ở gần người nói (cái ~ này)."},{"id":"cloze_minna_2_4","vocabId":"minna_2_4","targetWord":"その","targetReading":"その~","sentence":"（　　）かばんはだれのですか。…田中さんのです。","fullSentence":"そのかばんはだれのですか。…田中さんのです。","translation":"Cái cặp đó là của ai vậy? ...Là của anh Tanaka.","options":["この","その","あの","これ"],"correctIndex":1,"explanation":"「その」 đứng trước danh từ để chỉ vật ở gần người nghe (cái ~ đó)."},{"id":"cloze_minna_2_5","vocabId":"minna_2_5","targetWord":"あの","targetReading":"あの~","sentence":"（　　）人はミラーさんです。","fullSentence":"あの人はミラーさんです。","translation":"Người kia là anh Miller.","options":["この","その","あの","あれ"],"correctIndex":2,"explanation":"「あの」 đứng trước danh từ để chỉ người/vật ở xa cả hai người (người/vật ~ kia)."},{"id":"cloze_minna_2_6","vocabId":"minna_2_6","targetWord":"本","targetReading":"ほん","sentence":"これは日本語の（　　）です。","fullSentence":"これは日本語の本です。","translation":"Đây là cuốn sách tiếng Nhật.","options":["本","傘","かばん","時計"],"correctIndex":0,"explanation":"「本」（ほん） nghĩa là cuốn sách."},{"id":"cloze_minna_2_7","vocabId":"minna_2_7","targetWord":"辞書","targetReading":"じしょ","sentence":"言葉の意味を（　　）で調べます。","fullSentence":"言葉の意味を辞書で調べます。","translation":"Tra ý nghĩa của từ vựng bằng từ điển.","options":["手帳","辞書","雑誌","新聞"],"correctIndex":1,"explanation":"「辞書」（じしょ） nghĩa là cuốn từ điển."},{"id":"cloze_minna_2_8","vocabId":"minna_2_8","targetWord":"雑誌","targetReading":"ざっし","sentence":"これは自動車の（　　）です。写真がたくさんあります。","fullSentence":"これは自動車の雑誌です。写真がたくさんあります。","translation":"Đây là cuốn tạp chí về ô tô. Có rất nhiều hình ảnh.","options":["手帳","新聞","雑誌","ノート"],"correctIndex":2,"explanation":"「雑誌」（ざっし） nghĩa là cuốn tạp chí."},{"id":"cloze_minna_2_9","vocabId":"minna_2_9","targetWord":"新聞","targetReading":"しんぶん","sentence":"父は毎朝（　　）を読みます。","fullSentence":"父は毎朝新聞を読みます。","translation":"Bố tôi đọc báo mỗi sáng.","options":["新聞","辞書","時計","かぎ"],"correctIndex":0,"explanation":"「新聞」（しんぶん） nghĩa là tờ báo."},{"id":"cloze_minna_2_10","vocabId":"minna_2_10","targetWord":"ノート","targetReading":"ノート","sentence":"この（　　）に漢字を練習します。","fullSentence":"このノートに漢字を練習します。","translation":"Tôi luyện tập chữ Hán vào cuốn vở này.","options":["カード","ノート","雑誌","辞書"],"correctIndex":1,"explanation":"「ノート」 là từ mượn tiếng Anh (Notebook), nghĩa là cuốn vở."},{"id":"cloze_minna_2_11","vocabId":"minna_2_11","targetWord":"手帳","targetReading":"てちょう","sentence":"予定を（　　）に書きます。","fullSentence":"予定を手帳に書きます。","translation":"Tôi ghi lịch trình vào cuốn sổ tay.","options":["手帳","新聞","雑誌","傘"],"correctIndex":0,"explanation":"「手帳」（てちょう） nghĩa là cuốn sổ tay cá nhân bỏ túi."},{"id":"cloze_minna_2_12","vocabId":"minna_2_12","targetWord":"名刺","targetReading":"めいし","sentence":"社長の（　　）をいただきました。","fullSentence":"社長の名刺をいただきました。","translation":"Tôi đã nhận được danh thiếp của giám đốc.","options":["手帳","名刺","切手","雑誌"],"correctIndex":1,"explanation":"「名刺」（めいし） nghĩa là danh thiếp (card visit)."},{"id":"cloze_minna_2_13","vocabId":"minna_2_13","targetWord":"カード","targetReading":"カード","sentence":"財布の中に銀行の（　　）があります。","fullSentence":"財布の中に銀行のカードがあります。","translation":"Trong ví có thẻ ngân hàng.","options":["本","カード","かばん","時計"],"correctIndex":1,"explanation":"「カード」 nghĩa là chiếc thẻ (thẻ ngân hàng, thẻ từ...)."},{"id":"cloze_minna_2_14","vocabId":"minna_2_14","targetWord":"テレホンカード","targetReading":"テレホンカード","sentence":"公衆電話で（　　）を使います。","fullSentence":"公衆電話でテレホンカードを使います。","translation":"Dùng thẻ điện thoại ở bốt điện thoại công cộng.","options":["テレホンカード","名刺","ノート","手帳"],"correctIndex":0,"explanation":"「テレホンカード」 là thẻ điện thoại dùng cho bốt điện thoại công cộng."},{"id":"cloze_minna_2_15","vocabId":"minna_2_15","targetWord":"鉛筆","targetReading":"えんぴつ","sentence":"テストは（　　）で書いてください。","fullSentence":"テストは鉛筆で書いてください。","translation":"Xin hãy làm bài kiểm tra bằng bút chì.","options":["鉛筆","かぎ","傘","時計"],"correctIndex":0,"explanation":"「鉛筆」（えんぴつ） nghĩa là bút chì."},{"id":"cloze_minna_2_16","vocabId":"minna_2_16","targetWord":"ボールペン","targetReading":"ボールペン","sentence":"黒の（　　）で書類にサインします。","fullSentence":"黒のボールペンで書類にサインします。","translation":"Ký tên vào giấy tờ bằng bút bi màu đen.","options":["ノート","手帳","ボールペン","辞書"],"correctIndex":2,"explanation":"「ボールペン」 nghĩa là chiếc bút bi."},{"id":"cloze_minna_2_17","vocabId":"minna_2_17","targetWord":"シャープペンシル","targetReading":"シャープペンシル","sentence":"（　　）の芯を買いました。","fullSentence":"シャープペンシルの芯を買いました。","translation":"Tôi đã mua ruột chì cho chiếc bút chì bấm.","options":["ボールペン","シャープペンシル","テレホンカード","手帳"],"correctIndex":1,"explanation":"「シャープペンシル」 nghĩa là bút chì bấm (chì kim)."},{"id":"cloze_minna_2_18","vocabId":"minna_2_18","targetWord":"かぎ","targetReading":"かぎ","sentence":"部屋の（　　）をかばんに入れました。","fullSentence":"部屋のかぎをかばんに入れました。","translation":"Tôi đã để chìa khóa phòng vào trong cặp.","options":["かぎ","傘","時計","本"],"correctIndex":0,"explanation":"「かぎ」 nghĩa là chiếc chìa khóa."},{"id":"cloze_minna_2_19","vocabId":"minna_2_19","targetWord":"時計","targetReading":"とけい","sentence":"この（　　）は日本のセイコー製です。","fullSentence":"この時計は日本のセイコー製です。","translation":"Chiếc đồng hồ này do hãng Seiko của Nhật sản xuất.","options":["かさ","時計","かぎ","ノート"],"correctIndex":1,"explanation":"「時計」（とけい） nghĩa là đồng hồ."},{"id":"cloze_minna_2_20","vocabId":"minna_2_20","targetWord":"傘","targetReading":"かさ","sentence":"雨ですから、（　　）を持っていきます。","fullSentence":"雨ですから、傘を持っていきます。","translation":"Vì trời mưa nên tôi mang theo ô.","options":["傘","本","時計","かぎ"],"correctIndex":0,"explanation":"「傘」（かさ） nghĩa là chiếc ô, dù."},{"id":"cloze_minna_2_21","vocabId":"minna_2_21","targetWord":"かばん","targetReading":"かばん","sentence":"教科書を（　　）に入れます。","fullSentence":"教科書をかばんに入れます。","translation":"Cho sách giáo khoa vào trong cặp.","options":["机","かばん","時計","椅子"],"correctIndex":1,"explanation":"「かばん」 nghĩa là cặp sách, túi xách."},{"id":"cloze_minna_2_22","vocabId":"minna_2_22","targetWord":"テープ","targetReading":"[カセット] テーブ","sentence":"昔、カセット（　　）で音楽を聞きました。","fullSentence":"昔、カセットテープで音楽を聞きました。","translation":"Ngày xưa, người ta nghe nhạc bằng băng cát-xét.","options":["テープ","テレビ","ラジオ","カメラ"],"correctIndex":0,"explanation":"「カセットテープ」 nghĩa là cuộn băng cát-xét."},{"id":"cloze_minna_2_23","vocabId":"minna_2_23","targetWord":"テープレコーダー","targetReading":"テープレコーダー","sentence":"（　　）で先生の発音を録音します。","fullSentence":"テープレコーダーで先生の発音を録音します。","translation":"Ghi âm lại phát âm của giáo viên bằng máy ghi âm.","options":["テープレコーダー","テレビ","ラジオ","自動車"],"correctIndex":0,"explanation":"「テープレコーダー」 nghĩa là máy ghi âm / máy phát băng."},{"id":"cloze_minna_2_24","vocabId":"minna_2_24","targetWord":"テレビ","targetReading":"テレビ","sentence":"毎晩リビングで（　　）を見ます。","fullSentence":"毎晩リビングでテレビを見ます。","translation":"Mỗi tối tôi xem tivi ở phòng khách.","options":["ラジオ","テレビ","机","傘"],"correctIndex":1,"explanation":"「テレビ」 là từ mượn (Television), nghĩa là máy vô tuyến truyền hình (tivi)."},{"id":"cloze_minna_2_25","vocabId":"minna_2_25","targetWord":"ラジオ","targetReading":"ラジオ","sentence":"朝ごはんを食べながら（　　）を聞きます。","fullSentence":"朝ごはんを食べながらラジオを聞きます。","translation":"Tôi vừa nghe đài radio vừa ăn sáng.","options":["テレビ","ラジオ","カメラ","本"],"correctIndex":1,"explanation":"「ラジオ」 nghĩa là máy thu thanh (đài radio)."},{"id":"cloze_minna_2_26","vocabId":"minna_2_26","targetWord":"カメラ","targetReading":"カメラ","sentence":"旅行で（　　）を使って写真を撮ります。","fullSentence":"旅行でカメラを使って写真を撮ります。","translation":"Dùng máy ảnh chụp ảnh khi đi du lịch.","options":["テレビ","時計","カメラ","ラジオ"],"correctIndex":2,"explanation":"「カメラ」 nghĩa là chiếc máy ảnh."},{"id":"cloze_minna_2_27","vocabId":"minna_2_27","targetWord":"コンピュータ","targetReading":"コンピュータ","sentence":"会社で（　　）を使って仕事をします。","fullSentence":"会社でコンピュータを使って仕事をします。","translation":"Sử dụng máy vi tính để làm việc ở công ty.","options":["ラジオ","コンピュータ","テレビ","テープレコーダー"],"correctIndex":1,"explanation":"「コンピュータ」 nghĩa là máy vi tính (máy tính điện tử)."},{"id":"cloze_minna_2_28","vocabId":"minna_2_28","targetWord":"自動車","targetReading":"じどうしゃ","sentence":"日本の（　　）は世界中で人気があります。","fullSentence":"日本の自動車は世界中で人気があります。","translation":"Ô tô của Nhật Bản rất được ưa chuộng trên toàn thế giới.","options":["自動車","時計","ラジオ","机"],"correctIndex":0,"explanation":"「自動車」（じどうしゃ） nghĩa là xe ô tô, xe hơi."},{"id":"cloze_minna_2_29","vocabId":"minna_2_29","targetWord":"机","targetReading":"つくえ","sentence":"（　　）の上に本とノートがあります。","fullSentence":"机の上に本とノートがあります。","translation":"Trên bàn có sách và vở.","options":["いす","机","かばん","傘"],"correctIndex":1,"explanation":"「机」（つくえ） nghĩa là cái bàn làm việc, bàn học."},{"id":"cloze_minna_2_30","vocabId":"minna_2_30","targetWord":"いす","targetReading":"いす","sentence":"どうぞ、（　　）に座ってください。","fullSentence":"どうぞ、いすに座ってください。","translation":"Xin mời, hãy ngồi xuống ghế.","options":["机","いす","かばん","本"],"correctIndex":1,"explanation":"「いす」 nghĩa là cái ghế."},{"id":"cloze_minna_2_31","vocabId":"minna_2_31","targetWord":"チョコレート","targetReading":"チョコレート","sentence":"バレンタインデーに（　　）をあげます。","fullSentence":"バレンタインデーにチョコレートをあげます。","translation":"Tặng sô-cô-la vào ngày lễ tình nhân Valentine.","options":["コーヒー","チョコレート","タバコ","本"],"correctIndex":1,"explanation":"「チョコレート」 nghĩa là sô-cô-la."},{"id":"cloze_minna_2_32","vocabId":"minna_2_32","targetWord":"コーヒー","targetReading":"コーヒー","sentence":"喫茶店で温かい（　　）を飲みます。","fullSentence":"喫茶店で温かいコーヒーを飲みます。","translation":"Uống cà phê nóng ở quán giải khát.","options":["チョコレート","コーヒー","ラジオ","辞書"],"correctIndex":1,"explanation":"「コーヒー」 nghĩa là cà phê."},{"id":"cloze_minna_2_33","vocabId":"minna_2_33","targetWord":"英語","targetReading":"えいご","sentence":"ワット先生は大学で（　　）を教えています。","fullSentence":"ワット先生は大学で英語を教えています。","translation":"Thầy Watt dạy tiếng Anh ở trường đại học.","options":["日本語","英語","フランス","ドイツ"],"correctIndex":1,"explanation":"「英語」（えいご） nghĩa là tiếng Anh."},{"id":"cloze_minna_2_34","vocabId":"minna_2_34","targetWord":"日本語","targetReading":"にほんご","sentence":"（　　）の勉強はとても面白いです。","fullSentence":"日本語の勉強はとても面白いです。","translation":"Học tiếng Nhật rất là thú vị.","options":["英語","日本語","中国人","韓国"],"correctIndex":1,"explanation":"「日本語」（にほんご） nghĩa là tiếng Nhật."},{"id":"cloze_minna_2_35","vocabId":"minna_2_35","targetWord":"∼語","targetReading":"∼ご","sentence":"サントスさんはポルトガル（　　）を話します。","fullSentence":"サントスさんはポルトガル語を話します。","translation":"Anh Santos nói tiếng Bồ Đào Nha.","options":["人","語","本","年"],"correctIndex":1,"explanation":"Tên quốc gia + 「語」（ご） để chỉ ngôn ngữ của quốc gia đó."},{"id":"cloze_minna_2_36","vocabId":"minna_2_36","targetWord":"何","targetReading":"なん","sentence":"これは（　　）ですか。…名刺です。","fullSentence":"これは何ですか。…名刺です。","translation":"Đây là cái gì vậy? ...Là danh thiếp.","options":["だれ","どこ","何","いつ"],"correctIndex":2,"explanation":"「何」（なん） là từ để hỏi đồ vật (cái gì)."},{"id":"cloze_minna_2_37","vocabId":"minna_2_37","targetWord":"そう","targetReading":"そう","sentence":"それは辞書ですか。…はい、（　　）です。","fullSentence":"それは辞書ですか。…はい、そうです。","translation":"Đó là cuốn từ điển phải không? ...Vâng, đúng vậy.","options":["ちがいます","そう","だれ","これ"],"correctIndex":1,"explanation":"「はい、そうです」 dùng để xác nhận câu hỏi nghi vấn là đúng như vậy."},{"id":"cloze_minna_2_38","vocabId":"minna_2_38","targetWord":"違います。","targetReading":"ちがいます。","sentence":"これはミラーさんの傘ですか。…いいえ、（　　）。佐藤さんのです。","fullSentence":"これはミラーさんの傘ですか。…いいえ、違います。佐藤さんのです。","translation":"Đây có phải ô của anh Miller không? ...Không, nhầm rồi. Là của chị Sato.","options":["そうです","違います","わかりました","どういたしまして"],"correctIndex":1,"explanation":"「いいえ、違います」（ちがいます） dùng khi muốn phủ định thông tin (không phải, nhầm rồi)."},{"id":"cloze_minna_2_39","vocabId":"minna_2_39","targetWord":"そうですか。","targetReading":"そうですか。","sentence":"この傘は木村さんのですよ。…あ、（　　）。ありがとうございます。","fullSentence":"この傘は木村さんのですよ。…あ、そうですか。ありがとうございます。","translation":"Chiếc ô này là của chị Kimura đấy. ...A, thế à? Cảm ơn bạn nhé.","options":["そうですか","どうぞ","はじめまして","おねがいします"],"correctIndex":0,"explanation":"「そうですか」 dùng khi vừa tiếp nhận một thông tin mới từ người khác (vậy à, thế à)."},{"id":"cloze_minna_2_40","vocabId":"minna_2_40","targetWord":"あのう","targetReading":"あのう","sentence":"（　　）、これはほんの気持ちですが、どうぞ。","fullSentence":"あのう、これはほんの気持ちですが、どうぞ。","translation":"À ừm..., đây là chút lòng thành, xin mời nhận ạ.","options":["はい","あのう","さようなら","いいえ"],"correctIndex":1,"explanation":"「あのう」 dùng biểu thị sự ngập ngừng, e ngại một cách lịch sự trước khi mở lời."},{"id":"cloze_minna_2_41","vocabId":"minna_2_41","targetWord":"ほんの気持ちです","targetReading":"ほんのきもちです","sentence":"これは（　　）。どうぞお受け取りください。","fullSentence":"これはほんの気持ちです。どうぞお受け取りください。","translation":"Đây chỉ là chút quà nhỏ/chút lòng thành thôi. Xin anh vui lòng nhận cho.","options":["お世話になります","ほんの気持ちです","こちらこそ","失礼ですが"],"correctIndex":1,"explanation":"「ほんの気持ちです」 là câu nói khiêm tốn khi tặng quà cho ai đó (chút quà mọn)."},{"id":"cloze_minna_2_42","vocabId":"minna_2_42","targetWord":"どうぞ","targetReading":"どうぞ","sentence":"お茶が入りました。（　　）召し上がってください。","fullSentence":"お茶が入りました。どうぞ召し上がってください。","translation":"Trà đã pha xong rồi. Xin mời bạn dùng ạ.","options":["どうぞ","どうも","はい","いいえ"],"correctIndex":0,"explanation":"「どうぞ」 dùng để mời ai đó làm gì (xin mời)."},{"id":"cloze_minna_2_43","vocabId":"minna_2_43","targetWord":"どうも","targetReading":"どうも","sentence":"荷物を持ってくれて、（　　）ありがとう。","fullSentence":"荷物を持ってくれて、どうもありがとう。","translation":"Cảm ơn bạn nhiều vì đã xách hành lý giúp tôi.","options":["どうぞ","どうも","いいえ","じゃあ"],"correctIndex":1,"explanation":"「どうも」 dùng để tăng mức độ cảm ơn hoặc chào hỏi ngắn gọn."},{"id":"cloze_minna_2_44","vocabId":"minna_2_44","targetWord":"[どうも] ありがとう[ございます]","targetReading":"[どうも] ありがとう[ございます]","sentence":"素敵なプレゼントを（　　）。","fullSentence":"素敵なプレゼントをどうもありがとうございます。","translation":"Cảm ơn bạn rất nhiều vì món quà tuyệt vời.","options":["失礼します","どうもありがとうございます","ごちそうさまでした","お邪魔します"],"correctIndex":1,"explanation":"「どうもありがとうございます」 là lời cảm ơn trang trọng và lịch sự."},{"id":"cloze_minna_2_45","vocabId":"minna_2_45","targetWord":"これから お世話になります","targetReading":"これから おせわになります","sentence":"隣の部屋に引っ越してきました。（　　）。","fullSentence":"隣の部屋に引っ越してきました。これからお世話になります。","translation":"Tôi vừa chuyển đến phòng bên cạnh. Từ nay mong được anh/chị giúp đỡ.","options":["お邪魔しました","これからお世話になります","おかげさまで","いってきます"],"correctIndex":1,"explanation":"「これからお世話になります」 dùng khi bắt đầu một mối quan hệ hàng xóm, công việc mới."},{"id":"cloze_minna_2_46","vocabId":"minna_2_46","targetWord":"こちらこそ よろしく","targetReading":"こちらこそ よろしく","sentence":"どうぞよろしくお願いします。…（　　）。","fullSentence":"どうぞよろしくお願いします。…こちらこそよろしくお願いします。","translation":"Rất mong được anh giúp đỡ. ...Chính tôi mới mong được anh giúp đỡ.","options":["お疲れ様でした","こちらこそよろしくお願いします","ごめんなさい","いってらっしゃい"],"correctIndex":1,"explanation":"「こちらこそよろしくお願いします」 dùng đáp lại câu chào của đối phương để thể hiện sự tương hỗ."}]', 1789044388368, 1789044388368);

INSERT OR REPLACE INTO ai_lesson_exercises (id, lesson_id, sync_code, model, total_exercises, exercises_data, created_at, updated_at) VALUES ('minna_3_global', 'minna_3', 'global', 'curated-minna-i', 41, '[{"id":"cloze_minna_3_0","vocabId":"minna_3_0","targetWord":"ここ","targetReading":"ここ","sentence":"（　　）は教室です。学生がたくさんいます。","fullSentence":"ここは教室です。学生がたくさんいます。","translation":"Đây là phòng học. Có rất nhiều sinh viên.","options":["ここ","そこ","あそこ","どこ"],"correctIndex":0,"explanation":"「ここ」 chỉ vị trí ở gần người nói (chỗ này, ở đây)."},{"id":"cloze_minna_3_1","vocabId":"minna_3_1","targetWord":"そこ","targetReading":"そこ","sentence":"（　　）は受付ですか。…はい、そうです。","fullSentence":"そこは受付ですか。…はい、そうです。","translation":"Đó là quầy lễ tân phải không? ...Vâng, đúng vậy.","options":["ここ","そこ","あそこ","だれ"],"correctIndex":1,"explanation":"「そこ」 chỉ vị trí ở gần người nghe (chỗ đó, ở đó)."},{"id":"cloze_minna_3_2","vocabId":"minna_3_2","targetWord":"あそこ","targetReading":"あそこ","sentence":"（　　）は食堂です。遠くに見えます。","fullSentence":"あそこは食堂です。遠くに見えます。","translation":"Đằng kia là nhà ăn. Nhìn thấy ở đằng xa.","options":["ここ","そこ","あそこ","どちら"],"correctIndex":2,"explanation":"「あそこ」 chỉ vị trí ở xa cả người nói và người nghe (ở kia, chỗ kia)."},{"id":"cloze_minna_3_3","vocabId":"minna_3_3","targetWord":"どこ","targetReading":"どこ","sentence":"お手洗いは（　　）ですか。…あそこです。","fullSentence":"お手洗いはどこですか。…あそこです。","translation":"Nhà vệ sinh ở đâu vậy? ...Ở đằng kia.","options":["だれ","どこ","なん","いくら"],"correctIndex":1,"explanation":"「どこ」 là từ để hỏi vị trí, địa điểm (ở đâu, chỗ nào)."},{"id":"cloze_minna_3_4","vocabId":"minna_3_4","targetWord":"こちら","targetReading":"こちら","sentence":"エレベーターは（　　）でございます。","fullSentence":"エレベーターはこちらでございます。","translation":"Thang máy ở phía này ạ.","options":["こちら","そちら","あちら","どちら"],"correctIndex":0,"explanation":"「こちら」 là cách nói lịch sự chỉ hướng hoặc vị trí gần người nói (phía này, chỗ này)."},{"id":"cloze_minna_3_5","vocabId":"minna_3_5","targetWord":"そちら","targetReading":"そちら","sentence":"電話は（　　）でございます。","fullSentence":"電話はそちらでございます。","translation":"Điện thoại ở phía đó ạ.","options":["こちら","そちら","あちら","どこ"],"correctIndex":1,"explanation":"「そちら」 là cách nói lịch sự chỉ vị trí ở gần người nghe (phía đó, chỗ đó)."},{"id":"cloze_minna_3_6","vocabId":"minna_3_6","targetWord":"あちら","targetReading":"あちら","sentence":"会議室は（　　）でございます。","fullSentence":"会議室はあちらでございます。","translation":"Phòng họp ở phía đằng kia ạ.","options":["こちら","そちら","あちら","どちら"],"correctIndex":2,"explanation":"「あちら」 là cách nói lịch sự chỉ phương hướng ở xa cả hai người (phía kia)."},{"id":"cloze_minna_3_7","vocabId":"minna_3_7","targetWord":"どちら","targetReading":"どちら","sentence":"お国は（　　）ですか。…アメリカです。","fullSentence":"お国はどちらですか。…アメリカです。","translation":"Đất nước của bạn ở đâu (quốc tịch nước nào)? ...Là nước Mỹ.","options":["だれ","何","どちら","いくら"],"correctIndex":2,"explanation":"「どちら」 là cách hỏi lịch sự của どこ (ở đâu, phía nào, nước nào)."},{"id":"cloze_minna_3_8","vocabId":"minna_3_8","targetWord":"教室","targetReading":"きょうしつ","sentence":"学生は（　　）で日本語を勉強します。","fullSentence":"学生は教室で日本語を勉強します。","translation":"Sinh viên học tiếng Nhật ở phòng học.","options":["教室","食堂","事務所","部屋"],"correctIndex":0,"explanation":"「教室」（きょうしつ） nghĩa là phòng học, lớp học."},{"id":"cloze_minna_3_9","vocabId":"minna_3_9","targetWord":"食堂","targetReading":"しょくどう","sentence":"お昼休みに（　　）でご飯を食べます。","fullSentence":"お昼休みに食堂でご飯を食べます。","translation":"Tôi ăn cơm ở nhà ăn vào giờ nghỉ trưa.","options":["教室","会議室","食堂","事務所"],"correctIndex":2,"explanation":"「食堂」（しょくどう） nghĩa là nhà ăn, căng-tin."},{"id":"cloze_minna_3_10","vocabId":"minna_3_10","targetWord":"事務所","targetReading":"じむしょ","sentence":"先生は（　　）で書類を作っています。","fullSentence":"先生は事務所で書類を作っています。","translation":"Thầy giáo đang làm giấy tờ ở văn phòng.","options":["事務所","食堂","部屋","教室"],"correctIndex":0,"explanation":"「事務所」（じむしょ） nghĩa là văn phòng làm việc."},{"id":"cloze_minna_3_11","vocabId":"minna_3_11","targetWord":"会議室","targetReading":"かいぎしつ","sentence":"3階の（　　）で打ち合わせをします。","fullSentence":"3階の会議室で打ち合わせをします。","translation":"Chúng tôi họp bàn thảo luận ở phòng họp tầng 3.","options":["食堂","受付","会議室","教室"],"correctIndex":2,"explanation":"「会議室」（かいぎしつ） nghĩa là phòng họp."},{"id":"cloze_minna_3_12","vocabId":"minna_3_12","targetWord":"受付","targetReading":"うけつけ","sentence":"ビルの1階に（　　）があります。","fullSentence":"ビルの1階に受付があります。","translation":"Có quầy tiếp tân ở tầng 1 của tòa nhà.","options":["部屋","受付","食堂","教室"],"correctIndex":1,"explanation":"「受付」（うけつけ） nghĩa là quầy tiếp tân, lễ tân."},{"id":"cloze_minna_3_13","vocabId":"minna_3_13","targetWord":"ロビー","targetReading":"ロビー","sentence":"ホテルの（　　）で友達を待ちます。","fullSentence":"ホテルのロビーで友達を待ちます。","translation":"Tôi đợi bạn ở sảnh chờ của khách sạn.","options":["ロビー","教室","食堂","事務所"],"correctIndex":0,"explanation":"「ロビー」 (Lobby) nghĩa là sảnh chờ, hành lang phòng khách."},{"id":"cloze_minna_3_14","vocabId":"minna_3_14","targetWord":"部屋","targetReading":"へや","sentence":"わたしの（　　）は2階にあります。","fullSentence":"わたしの部屋は2階にあります。","translation":"Căn phòng của tôi ở tầng 2.","options":["部屋","靴","国","会社"],"correctIndex":0,"explanation":"「部屋」（へや） nghĩa là căn phòng."},{"id":"cloze_minna_3_15","vocabId":"minna_3_15","targetWord":"お手洗い","targetReading":"トイレ（おてあらい）","sentence":"すみません、（　　）はどこですか。","fullSentence":"すみません、お手洗いはどこですか。","translation":"Xin lỗi, nhà vệ sinh ở đâu vậy ạ?","options":["お手洗い","事務所","会議室","食堂"],"correctIndex":0,"explanation":"「お手洗い」（おてあらい） là cách nói lịch sự của nhà vệ sinh (toilet)."},{"id":"cloze_minna_3_16","vocabId":"minna_3_16","targetWord":"階段","targetReading":"かいだん","sentence":"エレベーターが混んでいますから、（　　）で行きます。","fullSentence":"エレベーターが混んでいますから、階段で行きます。","translation":"Vì thang máy đông nên tôi đi bằng cầu thang bộ.","options":["階段","電話","部屋","食堂"],"correctIndex":0,"explanation":"「階段」（かいだん） nghĩa là cầu thang bộ."},{"id":"cloze_minna_3_17","vocabId":"minna_3_17","targetWord":"エレベーター","targetReading":"エレベーター","sentence":"（　　）で8階へ上がります。","fullSentence":"エレベーターで8階へ上がります。","translation":"Lên tầng 8 bằng thang máy.","options":["エスカレーター","エレベーター","階段","ロビー"],"correctIndex":1,"explanation":"「エレベーター」 (Elevator) nghĩa là thang máy."},{"id":"cloze_minna_3_18","vocabId":"minna_3_18","targetWord":"エスカレーター","targetReading":"エスカレーター","sentence":"デパートの（　　）で2階へ行きます。","fullSentence":"デパートのエスカレーターで2階へ行きます。","translation":"Đi lên tầng 2 bằng thang cuốn của trung tâm thương mại.","options":["エスカレーター","エレベーター","電話","部屋"],"correctIndex":0,"explanation":"「エスカレーター」 (Escalator) nghĩa là thang cuốn."},{"id":"cloze_minna_3_19","vocabId":"minna_3_19","targetWord":"［お］国","targetReading":"［お］くに","sentence":"ミラーさんの（　　）はどちらですか。…アメリカです。","fullSentence":"ミラーさんのお国はどちらですか。…アメリカです。","translation":"Đất nước của anh Miller là ở đâu vậy? ...Là nước Mỹ.","options":["お国","会社","教室","受付"],"correctIndex":0,"explanation":"「［お］国」（おくに） là cách nói lịch sự tôn kính khi hỏi về quê hương, đất nước người khác."},{"id":"cloze_minna_3_20","vocabId":"minna_3_20","targetWord":"会社","targetReading":"かいしゃ","sentence":"父は自動車の（　　）に勤めています。","fullSentence":"父は自動車の会社に勤めています。","translation":"Bố tôi đang làm việc ở một công ty ô tô.","options":["部屋","会社","学校","国"],"correctIndex":1,"explanation":"「会社」（かいしゃ） nghĩa là công ty."},{"id":"cloze_minna_3_21","vocabId":"minna_3_21","targetWord":"うち","targetReading":"うち","sentence":"毎晩7時に（　　）へ帰ります。","fullSentence":"毎晩7時にうちへ帰ります。","translation":"Mỗi tối 7 giờ tôi trở về nhà.","options":["会社","事務所","うち","教室"],"correctIndex":2,"explanation":"「うち」 nghĩa là ngôi nhà, tổ ấm của mình."},{"id":"cloze_minna_3_22","vocabId":"minna_3_22","targetWord":"電話","targetReading":"でんわ","sentence":"事務所に（　　）があります。","fullSentence":"事務所に電話があります。","translation":"Ở văn phòng có điện thoại.","options":["電話","靴","傘","ワイン"],"correctIndex":0,"explanation":"「電話」（でんわ） nghĩa là máy điện thoại, cuộc gọi."},{"id":"cloze_minna_3_23","vocabId":"minna_3_23","targetWord":"靴","targetReading":"くつ","sentence":"ここで（　　）を脱いでください。","fullSentence":"ここで靴を脱いでください。","translation":"Xin hãy cởi giày ở đây.","options":["ネクタイ","靴","傘","かばん"],"correctIndex":1,"explanation":"「靴」（くつ） nghĩa là đôi giày, đôi dép."},{"id":"cloze_minna_3_24","vocabId":"minna_3_24","targetWord":"ネクタイ","targetReading":"ネクタイ","sentence":"会社員はスーツを着て、（　　）をしめます。","fullSentence":"会社員はスーツを着て、ネクタイをしめます。","translation":"Nhân viên công ty mặc âu phục và thắt cà vạt.","options":["靴","ネクタイ","ワイン","たばこ"],"correctIndex":1,"explanation":"「ネクタイ」 (Necktie) nghĩa là chiếc cà vạt."},{"id":"cloze_minna_3_25","vocabId":"minna_3_25","targetWord":"ワイン","targetReading":"ワイン","sentence":"フランスの（　　）はとてもおいしいです。","fullSentence":"フランスのワインはとてもおいしいです。","translation":"Rượu vang của Pháp rất là ngon.","options":["たばこ","靴","ワイン","ネクタイ"],"correctIndex":2,"explanation":"「ワイン」 (Wine) nghĩa là rượu vang nho."},{"id":"cloze_minna_3_26","vocabId":"minna_3_26","targetWord":"たばこ","targetReading":"たばこ","sentence":"教室で（　　）を吸ってはいけません。","fullSentence":"教室でたばこを吸ってはいけません。","translation":"Không được hút thuốc lá trong phòng học.","options":["たばこ","ワイン","靴","ネクタイ"],"correctIndex":0,"explanation":"「たばこ」 nghĩa là điếu thuốc lá."},{"id":"cloze_minna_3_27","vocabId":"minna_3_27","targetWord":"売り場","targetReading":"うりば","sentence":"ワインの（　　）は地下1階です。","fullSentence":"ワインの売り場は地下1階です。","translation":"Quầy bán rượu vang ở tầng hầm 1.","options":["売り場","教室","事務所","部屋"],"correctIndex":0,"explanation":"「売り場」（うりば） nghĩa là quầy hàng, gian hàng bày bán."},{"id":"cloze_minna_3_28","vocabId":"minna_3_28","targetWord":"地下","targetReading":"ちか","sentence":"デパートの（　　）に食品売り場があります。","fullSentence":"デパートの地下に食品売り場があります。","translation":"Dưới tầng hầm của trung tâm thương mại có quầy thực phẩm.","options":["地下","屋上","階段","ロビー"],"correctIndex":0,"explanation":"「地下」（ちか） nghĩa là tầng hầm, lòng đất."},{"id":"cloze_minna_3_29","vocabId":"minna_3_29","targetWord":"～階","targetReading":"～かい（～がい）","sentence":"会議室は3（　　）にあります。","fullSentence":"会議室は3階にあります。","translation":"Phòng họp ở tầng 3.","options":["階","円","歳","人"],"correctIndex":0,"explanation":"Số đếm + 「階」（かい/がい） dùng để chỉ số tầng của tòa nhà."},{"id":"cloze_minna_3_30","vocabId":"minna_3_30","targetWord":"何階","targetReading":"なんがい","sentence":"事務所は（　　）ですか。…2階です。","fullSentence":"事務所は何階ですか。…2階です。","translation":"Văn phòng ở tầng mấy vậy? ...Ở tầng 2.","options":["なんさい","何階","いくら","なんにん"],"correctIndex":1,"explanation":"「何階」（なんがい） là từ để hỏi số tầng (tầng mấy)."},{"id":"cloze_minna_3_31","vocabId":"minna_3_31","targetWord":"～円","targetReading":"～えん","sentence":"このノートは100（　　）です。","fullSentence":"このノートは100円です。","translation":"Cuốn vở này giá 100 yên.","options":["円","階","歳","人"],"correctIndex":0,"explanation":"「～円」（えん） là đơn vị tiền tệ Nhật Bản (Yên)."},{"id":"cloze_minna_3_32","vocabId":"minna_3_32","targetWord":"いくら","targetReading":"いくら","sentence":"このネクタイは（　　）ですか。…3,000円です。","fullSentence":"このネクタイはいくらですか。…3,000円です。","translation":"Cà vạt này giá bao nhiêu? ...3.000 yên.","options":["だれ","どこ","いくら","なんがい"],"correctIndex":2,"explanation":"「いくら」 là từ dùng để hỏi giá tiền (bao nhiêu tiền)."},{"id":"cloze_minna_3_33","vocabId":"minna_3_33","targetWord":"百","targetReading":"ひゃく","sentence":"このペンは（　　）円（100円）です。","fullSentence":"このペンは百円（100円）です。","translation":"Chiếc bút này giá một trăm yên.","options":["百","千","万","十"],"correctIndex":0,"explanation":"「百」（ひゃく） nghĩa là một trăm (100)."},{"id":"cloze_minna_3_34","vocabId":"minna_3_34","targetWord":"千","targetReading":"せん","sentence":"この本は（　　）円（1,000円）です。","fullSentence":"この本は千円（1,000円）です。","translation":"Cuốn sách này giá một nghìn yên.","options":["百","千","万","億"],"correctIndex":1,"explanation":"「千」（せん） nghĩa là một nghìn (1.000)."},{"id":"cloze_minna_3_35","vocabId":"minna_3_35","targetWord":"万","targetReading":"まん","sentence":"この時計は一（　　）円（10,000円）です。","fullSentence":"この時計は一万円（10,000円）です。","translation":"Chiếc đồng hồ này giá một vạn yên (10.000 yên).","options":["万","百","千","階"],"correctIndex":0,"explanation":"「万」（まん） là đơn vị mười nghìn (vạn, 10.000)."},{"id":"cloze_minna_3_36","vocabId":"minna_3_36","targetWord":"すみません。","targetReading":"すみません。","sentence":"（　　）、その靴を見せてください。","fullSentence":"すみません、その靴を見せてください。","translation":"Xin lỗi/Làm phiền bạn, làm ơn cho tôi xem đôi giày đó.","options":["ありがとうございます","すみません","失礼しました","ごちそうさま"],"correctIndex":1,"explanation":"「すみません」 dùng để gọi nhân viên hoặc mở đầu nhờ vả (xin lỗi, làm phiền)."},{"id":"cloze_minna_3_37","vocabId":"minna_3_37","targetWord":"～でございます。","targetReading":"～でございます。","sentence":"ワイン売り場は地下1階（　　）。","fullSentence":"ワイン売り場は地下1階でございます。","translation":"Quầy bán rượu vang ở tầng hầm 1 ạ.","options":["でございます","でした","じゃありません","ございますか"],"correctIndex":0,"explanation":"「でございます」 là dạng kính ngữ lịch sự của 「です」 mà nhân viên phục vụ hay dùng."},{"id":"cloze_minna_3_38","vocabId":"minna_3_38","targetWord":"［～を］みせてください。","targetReading":"［～を］みせてください。","sentence":"すみません、あの時計を（　　）。","fullSentence":"すみません、あの時計をみせてください。","translation":"Xin lỗi, làm ơn cho tôi xem chiếc đồng hồ kia.","options":["みせてください","たべてください","のんでください","かえってください"],"correctIndex":0,"explanation":"「［～を］みせてください」 dùng khi muốn nhân viên cho xem món hàng."},{"id":"cloze_minna_3_39","vocabId":"minna_3_39","targetWord":"じゃ","targetReading":"じゃ","sentence":"（　　）、その靴をください。","fullSentence":"じゃ、その靴をください。","translation":"Thế thì/vậy thì, hãy lấy cho tôi đôi giày đó.","options":["じゃ","はい","いいえ","どうも"],"correctIndex":0,"explanation":"「じゃ」 nghĩa là thế thì, vậy thì (dùng khi đưa ra quyết định mua đồ)."},{"id":"cloze_minna_3_40","vocabId":"minna_3_40","targetWord":"［～を］ください。","targetReading":"［～を］ください。","sentence":"このネクタイを（　　）。…かしこまりました。","fullSentence":"このネクタイをください。…かしこまりました。","translation":"Làm ơn cho tôi lấy chiếc cà vạt này. ...Tôi hiểu rồi ạ.","options":["みせてください","ください","いってください","おねがいします"],"correctIndex":1,"explanation":"「［～を］ください」 dùng khi quyết định mua món đồ (hãy bán/cho tôi món này)."}]', 1789044388368, 1789044388368);

INSERT OR REPLACE INTO ai_lesson_exercises (id, lesson_id, sync_code, model, total_exercises, exercises_data, created_at, updated_at) VALUES ('minna_4_global', 'minna_4', 'global', 'curated-minna-i', 55, '[{"id":"cloze_minna_4_0","vocabId":"minna_4_0","targetWord":"起きます","targetReading":"おきます","sentence":"わたしは毎朝6時に（　　）。","fullSentence":"わたしは毎朝6時に起きます。","translation":"Tôi thức dậy vào lúc 6 giờ mỗi sáng.","options":["起きます","寝ます","働きます","終わります"],"correctIndex":0,"explanation":"「起きます」（おきます） nghĩa là thức dậy."},{"id":"cloze_minna_4_1","vocabId":"minna_4_1","targetWord":"寝ます","targetReading":"ねます","sentence":"毎晩11時に（　　）。","fullSentence":"毎晩11時に寝ます。","translation":"Mỗi tối tôi đi ngủ lúc 11 giờ.","options":["起きます","寝ます","勉強します","休みます"],"correctIndex":1,"explanation":"「寝ます」（ねます） nghĩa là ngủ, đi ngủ."},{"id":"cloze_minna_4_2","vocabId":"minna_4_2","targetWord":"働きます","targetReading":"はたらきます","sentence":"父は銀行で（　　）。","fullSentence":"父は銀行で働きます。","translation":"Bố tôi làm việc ở ngân hàng.","options":["寝ます","働きます","起きます","終わります"],"correctIndex":1,"explanation":"「働きます」（はたらきます） nghĩa là làm việc, lao động."},{"id":"cloze_minna_4_3","vocabId":"minna_4_3","targetWord":"休みます","targetReading":"やすみます","sentence":"土曜日と日曜日は会社を（　　）。","fullSentence":"土曜日と日曜日は会社を休みます。","translation":"Thứ bảy và chủ nhật tôi nghỉ làm ở công ty.","options":["働きます","休みます","勉強します","起きます"],"correctIndex":1,"explanation":"「休みます」（やすみます） nghĩa là nghỉ ngơi, nghỉ phép."},{"id":"cloze_minna_4_4","vocabId":"minna_4_4","targetWord":"勉強します","targetReading":"べんきょうします","sentence":"毎晩日本語を（　　）。","fullSentence":"毎晩日本語を勉強します。","translation":"Mỗi tối tôi học tiếng Nhật.","options":["寝ます","勉強します","働きます","終わります"],"correctIndex":1,"explanation":"「勉強します」（べんきょうします） nghĩa là học tập."},{"id":"cloze_minna_4_5","vocabId":"minna_4_5","targetWord":"終わります","targetReading":"おわります","sentence":"仕事は午後5時に（　　）。","fullSentence":"仕事は午後5時に終わります。","translation":"Công việc kết thúc vào lúc 5 giờ chiều.","options":["起きます","始まります","終わります","寝ます"],"correctIndex":2,"explanation":"「終わります」（おわります） nghĩa là kết thúc, xong."},{"id":"cloze_minna_4_6","vocabId":"minna_4_6","targetWord":"デパート","targetReading":"デパート","sentence":"（　　）で服と靴を買いました。","fullSentence":"デパートで服と靴を買いました。","translation":"Tôi mua quần áo và giày ở trung tâm thương mại.","options":["デパート","郵便局","図書館","美術館"],"correctIndex":0,"explanation":"「デパート」 nghĩa là trung tâm thương mại, cửa hàng bách hóa."},{"id":"cloze_minna_4_7","vocabId":"minna_4_7","targetWord":"銀行","targetReading":"ぎんこう","sentence":"（　　）は午前9時から午後3時までです。","fullSentence":"銀行は午前9時から午後3時までです。","translation":"Ngân hàng mở cửa từ 9 giờ sáng đến 3 giờ chiều.","options":["郵便局","銀行","図書館","美術館"],"correctIndex":1,"explanation":"「銀行」（ぎんこう） nghĩa là ngân hàng."},{"id":"cloze_minna_4_8","vocabId":"minna_4_8","targetWord":"郵便局","targetReading":"ゆうびんきょく","sentence":"（　　）で手紙を出します。","fullSentence":"郵便局で手紙を出します。","translation":"Tôi gửi thư ở bưu điện.","options":["図書館","郵便局","銀行","デパート"],"correctIndex":1,"explanation":"「郵便局」（ゆうびんきょく） nghĩa là bưu điện."},{"id":"cloze_minna_4_9","vocabId":"minna_4_9","targetWord":"図書館","targetReading":"としょかん","sentence":"（　　）で本を借ります。","fullSentence":"図書館で本を借ります。","translation":"Tôi mượn sách ở thư viện.","options":["美術館","図書館","郵便局","銀行"],"correctIndex":1,"explanation":"「図書館」（としょかん） nghĩa là thư viện."},{"id":"cloze_minna_4_10","vocabId":"minna_4_10","targetWord":"美術館","targetReading":"びじゅつかん","sentence":"日曜日、（　　）で絵を見ました。","fullSentence":"日曜日、美術館で絵を見ました。","translation":"Chủ nhật, tôi đã đi xem tranh ở bảo tàng mỹ thuật.","options":["図書館","美術館","郵便局","銀行"],"correctIndex":1,"explanation":"「美術館」（びじゅつかん） nghĩa là bảo tàng mỹ thuật."},{"id":"cloze_minna_4_11","vocabId":"minna_4_11","targetWord":"今","targetReading":"いま","sentence":"（　　）、何時ですか。…4時です。","fullSentence":"今、何時ですか。…4時です。","translation":"Bây giờ là mấy giờ? ...Là 4 giờ.","options":["きのう","今","あした","おととい"],"correctIndex":1,"explanation":"「今」（いま） nghĩa là bây giờ, hiện tại."},{"id":"cloze_minna_4_12","vocabId":"minna_4_12","targetWord":"～時","targetReading":"～じ","sentence":"会議は午前10（　　）からです。","fullSentence":"会議は午前10時からです。","translation":"Cuộc họp bắt đầu từ 10 giờ sáng.","options":["時","分","歳","円"],"correctIndex":0,"explanation":"Số đếm + 「時」（じ） dùng để chỉ giờ."},{"id":"cloze_minna_4_13","vocabId":"minna_4_13","targetWord":"～分","targetReading":"～ふん","sentence":"今、2時15（　　）です。","fullSentence":"今、2時15分です。","translation":"Bây giờ là 2 giờ 15 phút.","options":["分","時","日","年"],"correctIndex":0,"explanation":"Số đếm + 「分」（ふん/ぷん） dùng để chỉ phút."},{"id":"cloze_minna_4_14","vocabId":"minna_4_14","targetWord":"半","targetReading":"はん","sentence":"毎朝7時（　　）に朝ごはんを食べます。","fullSentence":"毎朝7時半に朝ごはんを食べます。","translation":"Mỗi sáng tôi ăn sáng lúc 7 giờ rưỡi.","options":["半","分","時","前"],"correctIndex":0,"explanation":"「半」（はん） nghĩa là một nửa, 30 phút (rưỡi)."},{"id":"cloze_minna_4_15","vocabId":"minna_4_15","targetWord":"何時","targetReading":"なんじ","sentence":"今、（　　）ですか。…3時20分です。","fullSentence":"今、何時ですか。…3時20分です。","translation":"Bây giờ là mấy giờ? ...3 giờ 20 phút.","options":["何時","何曜日","何番","何歳"],"correctIndex":0,"explanation":"「何時」（なんじ） dùng để hỏi thời gian (mấy giờ)."},{"id":"cloze_minna_4_16","vocabId":"minna_4_16","targetWord":"何分","targetReading":"なんぷん","sentence":"テストはあと（　　）ですか。…あと10分です。","fullSentence":"テストはあと何分ですか。…あと10分です。","translation":"Bài kiểm tra còn lại mấy phút? ...Còn 10 phút nữa.","options":["何時","何分","何曜日","何番"],"correctIndex":1,"explanation":"「何分」（なんぷん） dùng để hỏi số phút (mấy phút)."},{"id":"cloze_minna_4_17","vocabId":"minna_4_17","targetWord":"午前","targetReading":"ごぜん","sentence":"（　　）9時に学校へ行きます。","fullSentence":"午前9時に学校へ行きます。","translation":"Tôi đến trường lúc 9 giờ sáng.","options":["午前","午後","今晩","おととい"],"correctIndex":0,"explanation":"「午前」（ごぜん） nghĩa là buổi sáng (a.m.)."},{"id":"cloze_minna_4_18","vocabId":"minna_4_18","targetWord":"午後","targetReading":"ごご","sentence":"（　　）3時にお茶を飲みます。","fullSentence":"午後3時にお茶を飲みます。","translation":"Tôi uống trà lúc 3 giờ chiều.","options":["午前","午後","あさって","けさ"],"correctIndex":1,"explanation":"「午後」（ごご） nghĩa là buổi chiều (p.m.)."},{"id":"cloze_minna_4_19","vocabId":"minna_4_19","targetWord":"朝","targetReading":"あさ","sentence":"（　　）ジョギングをします。空気がきれいです。","fullSentence":"朝ジョギングをします。空気がきれいです。","translation":"Buổi sáng tôi chạy bộ. Không khí rất trong lành.","options":["昼","晩","朝","夜"],"correctIndex":2,"explanation":"「朝」（あさ） nghĩa là buổi sáng."},{"id":"cloze_minna_4_20","vocabId":"minna_4_20","targetWord":"昼","targetReading":"ひる","sentence":"（　　）は食堂でラーメンを食べました。","fullSentence":"昼は食堂でラーメンを食べました。","translation":"Buổi trưa tôi đã ăn mì ramen ở nhà ăn.","options":["朝","昼","夜","晩"],"correctIndex":1,"explanation":"「昼」（ひる） nghĩa là buổi trưa, ban ngày."},{"id":"cloze_minna_4_21","vocabId":"minna_4_21","targetWord":"晩","targetReading":"ばん（よる）","sentence":"（　　）家族と一緒にテレビを見ます。","fullSentence":"晩家族と一緒にテレビを見ます。","translation":"Buổi tối tôi cùng gia đình xem tivi.","options":["朝","昼","晩","けさ"],"correctIndex":2,"explanation":"「晩」（ばん） hoặc 「夜」（よる） nghĩa là buổi tối, đêm."},{"id":"cloze_minna_4_22","vocabId":"minna_4_22","targetWord":"おととい","targetReading":"おととい","sentence":"（　　）雨が降りました。一昨日です。","fullSentence":"おととい雨が降りました。一昨日です。","translation":"Hôm kia trời đã đổ mưa.","options":["きのう","おととい","あした","あさって"],"correctIndex":1,"explanation":"「おととい」 nghĩa là hôm kia (2 ngày trước)."},{"id":"cloze_minna_4_23","vocabId":"minna_4_23","targetWord":"きのう","targetReading":"きのう","sentence":"（　　）デパートへ行きました。","fullSentence":"きのうデパートへ行きました。","translation":"Hôm qua tôi đã đến trung tâm thương mại.","options":["きょう","あした","きのう","あさって"],"correctIndex":2,"explanation":"「きのう」 nghĩa là ngày hôm qua."},{"id":"cloze_minna_4_24","vocabId":"minna_4_24","targetWord":"きょう","targetReading":"きょう","sentence":"（　　）は何曜日ですか。…金曜日です。","fullSentence":"きょうは何曜日ですか。…金曜日です。","translation":"Hôm nay là thứ mấy? ...Là thứ sáu.","options":["きょう","きのう","あした","おととい"],"correctIndex":0,"explanation":"「きょう」 nghĩa là ngày hôm nay."},{"id":"cloze_minna_4_25","vocabId":"minna_4_25","targetWord":"あした","targetReading":"あした","sentence":"（　　）テストがありますから、今晩勉強します。","fullSentence":"あしたテストがありますから、今晩勉強します。","translation":"Vì ngày mai có bài kiểm tra nên tối nay tôi sẽ học.","options":["きのう","おととい","あした","けさ"],"correctIndex":2,"explanation":"「あした」 nghĩa là ngày mai."},{"id":"cloze_minna_4_26","vocabId":"minna_4_26","targetWord":"あさって","targetReading":"あさって","sentence":"あしたは土曜日で、（　　）は日曜日です。","fullSentence":"あしたは土曜日で、あさっては日曜日です。","translation":"Ngày mai là thứ bảy, và ngày kia là chủ nhật.","options":["きのう","あさって","おととい","きょう"],"correctIndex":1,"explanation":"「あさって」 nghĩa là ngày kia (2 ngày sau)."},{"id":"cloze_minna_4_27","vocabId":"minna_4_27","targetWord":"けさ","targetReading":"けさ","sentence":"（　　）パンを食べました。今朝です。","fullSentence":"けさパンを食べました。今朝です。","translation":"Sáng nay tôi đã ăn bánh mì.","options":["けさ","今晩","まいあさ","まいばん"],"correctIndex":0,"explanation":"「けさ」（今朝） nghĩa là sáng nay."},{"id":"cloze_minna_4_28","vocabId":"minna_4_28","targetWord":"今晩","targetReading":"こんばん","sentence":"（　　）映画を見に行きます。","fullSentence":"今晩映画を見に行きます。","translation":"Tối nay tôi sẽ đi xem phim.","options":["けさ","今晩","おととい","きのう"],"correctIndex":1,"explanation":"「今晩」（こんばん） nghĩa là tối nay."},{"id":"cloze_minna_4_29","vocabId":"minna_4_29","targetWord":"休み","targetReading":"やすみ","sentence":"銀行の（　　）は土曜日と日曜日です。","fullSentence":"銀行の休みは土曜日と日曜日です。","translation":"Ngày nghỉ của ngân hàng là thứ bảy và chủ nhật.","options":["仕事","休み","勉強","番号"],"correctIndex":1,"explanation":"「休み」（やすみ） là danh từ nghĩa là ngày nghỉ, kỳ nghỉ."},{"id":"cloze_minna_4_30","vocabId":"minna_4_30","targetWord":"昼休み","targetReading":"ひるやすみ","sentence":"（　　）は12時から1時までです。","fullSentence":"昼休みは12時から1時までです。","translation":"Nghỉ trưa là từ 12 giờ đến 1 giờ.","options":["昼休み","今晩","朝","夜"],"correctIndex":0,"explanation":"「昼休み」（ひるやすみ） nghĩa là giờ nghỉ trưa."},{"id":"cloze_minna_4_31","vocabId":"minna_4_31","targetWord":"毎朝","targetReading":"まいあさ","sentence":"（　　）新聞を読みます。","fullSentence":"毎朝新聞を読みます。","translation":"Mỗi sáng tôi đều đọc báo.","options":["けさ","毎朝","毎晩","あした"],"correctIndex":1,"explanation":"「毎朝」（まいあさ） nghĩa là mỗi buổi sáng."},{"id":"cloze_minna_4_32","vocabId":"minna_4_32","targetWord":"毎晩","targetReading":"まいばん","sentence":"（　　）日記を書きます。","fullSentence":"毎晩日記を書きます。","translation":"Mỗi tối tôi đều viết nhật ký.","options":["毎朝","毎晩","毎日","けさ"],"correctIndex":1,"explanation":"「毎晩」（まいばん） nghĩa là mỗi buổi tối."},{"id":"cloze_minna_4_33","vocabId":"minna_4_33","targetWord":"毎日","targetReading":"まいにち","sentence":"（　　）日本語を勉強します。休みはありません。","fullSentence":"毎日日本語を勉強します。休みはありません。","translation":"Mỗi ngày tôi đều học tiếng Nhật. Không có ngày nghỉ.","options":["毎日","きのう","おととい","あさって"],"correctIndex":0,"explanation":"「毎日」（まいにち） nghĩa là mỗi ngày, hàng ngày."},{"id":"cloze_minna_4_34","vocabId":"minna_4_43","targetWord":"月曜日","targetReading":"げつようび","sentence":"週の始まりは（　　）です。","fullSentence":"週の始まりは月曜日です。","translation":"Khởi đầu của tuần là thứ hai.","options":["月曜日","火曜日","水曜日","木曜日"],"correctIndex":0,"explanation":"「月曜日」（げつようび） nghĩa là thứ hai."},{"id":"cloze_minna_4_35","vocabId":"minna_4_35","targetWord":"火曜日","targetReading":"かようび","sentence":"月曜日の次は（　　）です。","fullSentence":"月曜日の次は火曜日です。","translation":"Tiếp sau thứ hai là thứ ba.","options":["火曜日","水曜日","金曜日","日曜日"],"correctIndex":0,"explanation":"「火曜日」（かようび） nghĩa là thứ ba."},{"id":"cloze_minna_4_36","vocabId":"minna_4_36","targetWord":"水曜日","targetReading":"すいようび","sentence":"（　　）は週の真ん中の日です。","fullSentence":"水曜日は週の真ん中の日です。","translation":"Thứ tư là ngày giữa tuần.","options":["水曜日","木曜日","土曜日","月曜日"],"correctIndex":0,"explanation":"「水曜日」（すいようび） nghĩa là thứ tư."},{"id":"cloze_minna_4_37","vocabId":"minna_4_37","targetWord":"木曜日","targetReading":"もくようび","sentence":"金曜日の前は（　　）です。","fullSentence":"金曜日の前は木曜日です。","translation":"Trước thứ sáu là thứ năm.","options":["木曜日","火曜日","土曜日","日曜日"],"correctIndex":0,"explanation":"「木曜日」（もくようび） nghĩa là thứ năm."},{"id":"cloze_minna_4_38","vocabId":"minna_4_38","targetWord":"金曜日","targetReading":"きんようび","sentence":"（　　）の夜、友達と食事に行きます。","fullSentence":"金曜日の夜、友達と食事に行きます。","translation":"Tối thứ sáu tôi đi ăn cùng bạn bè.","options":["金曜日","月曜日","火曜日","水曜日"],"correctIndex":0,"explanation":"「金曜日」（きんようび） nghĩa là thứ sáu."},{"id":"cloze_minna_4_39","vocabId":"minna_4_39","targetWord":"土曜日","targetReading":"どようび","sentence":"（　　）は学校が休みです。","fullSentence":"土曜日は学校が休みです。","translation":"Thứ bảy trường học được nghỉ.","options":["月曜日","火曜日","水曜日","土曜日"],"correctIndex":3,"explanation":"「土曜日」（どようび） nghĩa là thứ bảy."},{"id":"cloze_minna_4_40","vocabId":"minna_4_40","targetWord":"日曜日","targetReading":"にちようび","sentence":"（　　）に家族と公園へ行きます。","fullSentence":"日曜日に家族と公園へ行きます。","translation":"Chủ nhật tôi cùng gia đình đi công viên.","options":["月曜日","木曜日","日曜日","火曜日"],"correctIndex":2,"explanation":"「日曜日」（にちようび） nghĩa là chủ nhật."},{"id":"cloze_minna_4_41","vocabId":"minna_4_41","targetWord":"何曜日","targetReading":"なんようび","sentence":"きょうは（　　）ですか。…水曜日です。","fullSentence":"きょうは何曜日ですか。…水曜日です。","translation":"Hôm nay là thứ mấy? ...Là thứ tư.","options":["何時","何曜日","何番","何日"],"correctIndex":1,"explanation":"「何曜日」（なんようび） dùng để hỏi ngày trong tuần (thứ mấy)."},{"id":"cloze_minna_4_42","vocabId":"minna_4_42","targetWord":"番号","targetReading":"ばんごう","sentence":"電話（　　）を教えてください。","fullSentence":"電話番号を教えてください。","translation":"Xin hãy chỉ cho tôi số điện thoại của bạn.","options":["番号","手帳","時計","名前"],"correctIndex":0,"explanation":"「番号」（ばんごう） nghĩa là số, số hiệu."},{"id":"cloze_minna_4_43","vocabId":"minna_4_43","targetWord":"何番","targetReading":"なんばん","sentence":"部屋は（　　）ですか。…302号室です。","fullSentence":"部屋は何番ですか。…302号室です。","translation":"Phòng là số mấy vậy? ...Là phòng số 302.","options":["何番","何階","何時","何曜日"],"correctIndex":0,"explanation":"「何番」（なんばん） dùng để hỏi số thứ tự, số hiệu (số mấy)."},{"id":"cloze_minna_4_44","vocabId":"minna_4_44","targetWord":"～から","targetReading":"～から","sentence":"9時（　　）5時まで働きます。","fullSentence":"9時から5時まで働きます。","translation":"Tôi làm việc từ 9 giờ đến 5 giờ.","options":["から","まで","と","へ"],"correctIndex":0,"explanation":"Trợ từ 「から」 dùng để chỉ điểm xuất phát về thời gian hoặc địa điểm (từ...)."},{"id":"cloze_minna_4_45","vocabId":"minna_4_45","targetWord":"～まで","targetReading":"～まで","sentence":"月曜日から金曜日（　　）学校があります。","fullSentence":"月曜日から金曜日まで学校があります。","translation":"Có giờ học ở trường từ thứ hai đến thứ sáu.","options":["から","まで","と","の"],"correctIndex":1,"explanation":"Trợ từ 「まで」 dùng để chỉ giới hạn kết thúc về thời gian hoặc địa điểm (đến...)."},{"id":"cloze_minna_4_46","vocabId":"minna_4_46","targetWord":"～と～","targetReading":"～と～","sentence":"休みは土曜日（　　）日曜日です。","fullSentence":"休みは土曜日と日曜日です。","translation":"Ngày nghỉ là thứ bảy và chủ nhật.","options":["と","から","まで","も"],"correctIndex":0,"explanation":"Trợ từ 「と」 dùng nối hai danh từ tương đương (và, với)."},{"id":"cloze_minna_4_47","vocabId":"minna_4_47","targetWord":"そちら","targetReading":"そちら","sentence":"（　　）は何時までですか。…午後6時までです。","fullSentence":"そちらは何時までですか。…午後6時までです。","translation":"Phía đằng bạn mở cửa đến mấy giờ? ...Đến 6 giờ chiều.","options":["こちら","そちら","あちら","どちら"],"correctIndex":1,"explanation":"「そちら」 chỉ phía đối phương khi nói chuyện qua điện thoại (bên bạn, phía bạn)."},{"id":"cloze_minna_4_48","vocabId":"minna_4_48","targetWord":"大変ですね。","targetReading":"たいへんですね。","sentence":"毎晩12時まで残業します。…それは（　　）。","fullSentence":"毎晩12時まで残業します。…それは大変ですね。","translation":"Mỗi tối tôi tăng ca đến 12 giờ đêm. ...Thế thì vất vả quá nhỉ.","options":["おめでとう","大変ですね","よかったですね","はじめまして"],"correctIndex":1,"explanation":"「大変ですね」（たいへんですね） thể hiện sự thấu hiểu và cảm thông khi người khác gặp vất vả."},{"id":"cloze_minna_4_49","vocabId":"minna_4_49","targetWord":"えーと","targetReading":"えーと","sentence":"電話番号は、（　　）…345の6789です。","fullSentence":"電話番号は、えーと…345の6789です。","translation":"Số điện thoại là, à ừm... 345-6789.","options":["えーと","はい","いいえ","どうぞ"],"correctIndex":0,"explanation":"「えーと」 là từ đệm dùng khi đang suy nghĩ hoặc nhớ lại thông tin (à, ừm)."},{"id":"cloze_minna_4_50","vocabId":"minna_4_50","targetWord":"104","targetReading":"104","sentence":"電話番号案内は（　　）番です。","fullSentence":"電話番号案内は104番です。","translation":"Tổng đài hướng dẫn tra cứu số điện thoại ở Nhật là số 104.","options":["104","110","119","100"],"correctIndex":0,"explanation":"「104」 là số tổng đài tra cứu danh bạ điện thoại tại Nhật Bản."},{"id":"cloze_minna_4_51","vocabId":"minna_4_51","targetWord":"お願いします。","targetReading":"おねがいします。","sentence":"大和美術館の電話番号を（　　）。","fullSentence":"大和美術館の電話番号をお願いします。","translation":"Làm ơn cho tôi hỏi số điện thoại của bảo tàng mỹ thuật Yamato.","options":["お願いします","いってください","みてください","ありました"],"correctIndex":0,"explanation":"「お願いします」（おねがいします） dùng khi yêu cầu dịch vụ hoặc nhờ giúp đỡ."},{"id":"cloze_minna_4_52","vocabId":"minna_4_52","targetWord":"かしこまりました。","targetReading":"かしこまりました。","sentence":"チケットを2枚ください。…はい、（　　）。","fullSentence":"チケットを2枚ください。…はい、かしこまりました。","translation":"Làm ơn bán cho tôi 2 vé. ...Vâng, tôi hiểu rồi/có ngay ạ.","options":["かしこまりました","わかりません","どういたしまして","ごめんなさい"],"correctIndex":0,"explanation":"「かしこまりました」 là câu trả lời chuẩn mực của nhân viên phục vụ khi tiếp nhận yêu cầu."},{"id":"cloze_minna_4_53","vocabId":"minna_4_53","targetWord":"お問い合わせの番号","targetReading":"おといあわせのばんごう","sentence":"（　　）は03-3456-7890です。","fullSentence":"お問い合わせの番号は03-3456-7890です。","translation":"Số điện thoại mà quý khách đang hỏi là 03-3456-7890.","options":["お問い合わせの番号","わたしの番号","部屋の番号","銀行の番号"],"correctIndex":0,"explanation":"「お問い合わせの番号」（おといあわせのばんごう） là câu thông báo số điện thoại khách hàng vừa hỏi."},{"id":"cloze_minna_4_54","vocabId":"minna_4_54","targetWord":"［どうも］ありがとうごさいました。","targetReading":"［どうも］ありがとうごさいました","sentence":"番号を教えてくれて、（　　）。","fullSentence":"番号を教えてくれて、どうもありがとうございました。","translation":"Cảm ơn bạn rất nhiều vì đã chỉ cho tôi số điện thoại.","options":["失礼します","どうもありがとうございました","お疲れ様でした","ごめんなさい"],"correctIndex":1,"explanation":"「どうもありがとうございました」 là lời cảm ơn cho sự giúp đỡ đã hoàn thành xong."}]', 1789044388368, 1789044388368);

INSERT OR REPLACE INTO ai_lesson_exercises (id, lesson_id, sync_code, model, total_exercises, exercises_data, created_at, updated_at) VALUES ('minna_5_global', 'minna_5', 'global', 'curated-minna-i', 55, '[{"id":"cloze_minna_5_0","vocabId":"minna_5_0","targetWord":"行きます","targetReading":"いきます","sentence":"あした東京へ（　　）。","fullSentence":"あした東京へ行きます。","translation":"Ngày mai tôi sẽ đi Tokyo.","options":["行きます","来ます","帰ります","寝ます"],"correctIndex":0,"explanation":"「行きます」（いきます） nghĩa là đi (rời khỏi vị trí hiện tại đến nơi khác)."},{"id":"cloze_minna_5_1","vocabId":"minna_5_1","targetWord":"来ます","targetReading":"きます","sentence":"ミラーさんはきのう日本へ（　　）。","fullSentence":"ミラーさんはきのう日本へ来ました。","translation":"Anh Miller đã đến Nhật Bản vào ngày hôm qua.","options":["行きます","来ました","帰りました","起きました"],"correctIndex":1,"explanation":"「来ます」（きます） nghĩa là đến (di chuyển về phía người nói)."},{"id":"cloze_minna_5_2","vocabId":"minna_5_2","targetWord":"帰ります","targetReading":"かえります","sentence":"夕方6時にうちへ（　　）。","fullSentence":"夕方6時にうちへ帰ります。","translation":"6 giờ chiều tôi trở về nhà.","options":["行きます","来ます","帰ります","休みます"],"correctIndex":2,"explanation":"「帰ります」（かえります） nghĩa là trở về nhà hoặc quê hương."},{"id":"cloze_minna_5_3","vocabId":"minna_5_3","targetWord":"学校","targetReading":"がっこう","sentence":"毎朝自転車で（　　）へ行きます。","fullSentence":"毎朝自転車で学校へ行きます。","translation":"Mỗi sáng tôi đi xe đạp đến trường học.","options":["学校","スーパー","駅","病院"],"correctIndex":0,"explanation":"「学校」（がっこう） nghĩa là trường học."},{"id":"cloze_minna_5_4","vocabId":"minna_5_4","targetWord":"スーパー","targetReading":"スーパー","sentence":"（　　）で野菜と果物を買います。","fullSentence":"スーパーで野菜と果物を買います。","translation":"Tôi mua rau và trái cây ở siêu thị.","options":["駅","スーパー","学校","飛行機"],"correctIndex":1,"explanation":"「スーパー」 (Supermarket) nghĩa là siêu thị."},{"id":"cloze_minna_5_5","vocabId":"minna_5_5","targetWord":"駅","targetReading":"えき","sentence":"（　　）で友達を待ちます。電車が来ます。","fullSentence":"駅で友達を待ちます。電車が来ます。","translation":"Tôi đợi bạn ở nhà ga. Tàu điện đang tới.","options":["学校","駅","スーパー","美術館"],"correctIndex":1,"explanation":"「駅」（えき） nghĩa là nhà ga xe lửa / tàu điện."},{"id":"cloze_minna_5_6","vocabId":"minna_5_6","targetWord":"飛行機","targetReading":"ひこうき","sentence":"ベトナムから日本まで（　　）で行きます。","fullSentence":"ベトナムから日本まで飛行機で行きます。","translation":"Đi từ Việt Nam đến Nhật Bản bằng máy bay.","options":["飛行機","船","電車","自転車"],"correctIndex":0,"explanation":"「飛行機」（ひこうき） nghĩa là máy bay."},{"id":"cloze_minna_5_7","vocabId":"minna_5_7","targetWord":"船","targetReading":"ふね","sentence":"海を（　　）で渡ります。","fullSentence":"海を船で渡ります。","translation":"Vượt biển bằng tàu thủy / thuyền.","options":["飛行機","電車","船","バス"],"correctIndex":2,"explanation":"「船」（ふね） nghĩa là thuyền, tàu thủy."},{"id":"cloze_minna_5_8","vocabId":"minna_5_8","targetWord":"電車","targetReading":"でんしゃ","sentence":"東京では多くの人が（　　）で通勤します。","fullSentence":"東京では多くの人が電車で通勤します。","translation":"Ở Tokyo nhiều người đi làm bằng tàu điện.","options":["電車","船","飛行機","タクシー"],"correctIndex":0,"explanation":"「電車」（でんしゃ） nghĩa là tàu điện."},{"id":"cloze_minna_5_9","vocabId":"minna_5_9","targetWord":"地下鉄","targetReading":"ちかてつ","sentence":"（　　）に乗って銀座へ行きます。","fullSentence":"地下鉄に乗って銀座へ行きます。","translation":"Đi tàu điện ngầm đến Ginza.","options":["地下鉄","飛行機","船","自転車"],"correctIndex":0,"explanation":"「地下鉄」（ちかてつ） nghĩa là tàu điện ngầm."},{"id":"cloze_minna_5_10","vocabId":"minna_5_10","targetWord":"新幹線","targetReading":"しんかんせん","sentence":"京都まで（　　）で行きます。とても速いです。","fullSentence":"京都まで新幹線で行きます。とても速いです。","translation":"Đi đến Kyoto bằng tàu Shinkansen. Rất là nhanh.","options":["新幹線","自転車","バス","船"],"correctIndex":0,"explanation":"「新幹線」（しんかんせん） là tàu siêu tốc của Nhật Bản."},{"id":"cloze_minna_5_11","vocabId":"minna_5_11","targetWord":"バス","targetReading":"バス","sentence":"駅前から（　　）に乗って大学へ行きます。","fullSentence":"駅前からバスに乗って大学へ行きます。","translation":"Bắt xe buýt từ trước nhà ga đến trường đại học.","options":["船","飛行機","バス","新幹線"],"correctIndex":2,"explanation":"「バス」 (Bus) nghĩa là xe buýt."},{"id":"cloze_minna_5_12","vocabId":"minna_5_12","targetWord":"タクシー","targetReading":"タクシー","sentence":"荷物が多いですから、（　　）で行きましょう。","fullSentence":"荷物が多いですから、タクシーで行きましょう。","translation":"Vì nhiều hành lý nên chúng ta hãy đi bằng taxi nhé.","options":["自転車","タクシー","歩いて","地下鉄"],"correctIndex":1,"explanation":"「タクシー」 (Taxi) nghĩa là xe taxi."},{"id":"cloze_minna_5_13","vocabId":"minna_5_13","targetWord":"自転車","targetReading":"じてんしゃ","sentence":"天気がいいので、（　　）で公園へ行きます。","fullSentence":"天気がいいので、自転車で公園へ行きます。","translation":"Vì thời tiết đẹp nên tôi đi xe đạp tới công viên.","options":["飛行機","船","自転車","新幹線"],"correctIndex":2,"explanation":"「自転車」（じてんしゃ） nghĩa là xe đạp."},{"id":"cloze_minna_5_14","vocabId":"minna_5_14","targetWord":"歩いて","targetReading":"あるいて","sentence":"駅からうちまで（　　）帰ります。10分です。","fullSentence":"駅からうちまで歩いて帰ります。10分です。","translation":"Từ nhà ga về nhà tôi đi bộ. Mất 10 phút.","options":["電車で","歩いて","タクシーで","飛行機で"],"correctIndex":1,"explanation":"「歩いて」（あるいて） nghĩa là đi bộ (không dùng trợ từ で)."},{"id":"cloze_minna_5_15","vocabId":"minna_5_15","targetWord":"人","targetReading":"ひと","sentence":"あの（　　）はだれですか。…サントスさんです。","fullSentence":"あの人はだれですか。…サントスさんです。","translation":"Người kia là ai vậy? ...Là anh Santos.","options":["人","友達","家族","彼"],"correctIndex":0,"explanation":"「人」（ひと） nghĩa là con người, người."},{"id":"cloze_minna_5_16","vocabId":"minna_5_16","targetWord":"友達","targetReading":"ともだち","sentence":"日曜日、（　　）と映画を見に行きます。","fullSentence":"日曜日、友達と映画を見に行きます。","translation":"Chủ nhật tôi đi xem phim cùng bạn bè.","options":["一人で","友達","学校","駅"],"correctIndex":1,"explanation":"「友達」（ともだち） nghĩa là bạn bè."},{"id":"cloze_minna_5_17","vocabId":"minna_5_17","targetWord":"彼","targetReading":"かれ","sentence":"（　　）はとても親切な人です。","fullSentence":"彼はとても親切な人です。","translation":"Anh ấy là một người rất tốt bụng.","options":["彼女","彼","家族","友達"],"correctIndex":1,"explanation":"「彼」（かれ） nghĩa là anh ấy, bạn trai."},{"id":"cloze_minna_5_18","vocabId":"minna_5_18","targetWord":"彼女","targetReading":"かのじょ","sentence":"（　　）は日本語の先生です。","fullSentence":"彼女は日本語の先生です。","translation":"Cô ấy là giáo viên tiếng Nhật.","options":["彼","彼女","家族","一人"],"correctIndex":1,"explanation":"「彼女」（かのじょ） nghĩa là cô ấy, bạn gái."},{"id":"cloze_minna_5_19","vocabId":"minna_5_19","targetWord":"家族","targetReading":"かぞく","sentence":"去年の夏、（　　）と一緒に旅行しました。","fullSentence":"去年の夏、家族と一緒に旅行しました。","translation":"Mùa hè năm ngoái tôi đã đi du lịch cùng gia đình.","options":["一人","家族","学校","スーパー"],"correctIndex":1,"explanation":"「家族」（かぞく） nghĩa là gia đình."},{"id":"cloze_minna_5_20","vocabId":"minna_5_20","targetWord":"一人で","targetReading":"ひとりで","sentence":"だれと日本へ来ましたか。…（　　）来ました。","fullSentence":"だれと日本へ来ましたか。…一人で来ました。","translation":"Bạn đã đến Nhật Bản cùng với ai? ...Tôi đã đến một mình.","options":["友達と","家族と","一人で","彼女と"],"correctIndex":2,"explanation":"「一人で」（ひとりで） nghĩa là một mình (tự thân làm)."},{"id":"cloze_minna_5_21","vocabId":"minna_5_21","targetWord":"先週","targetReading":"せんしゅう","sentence":"（　　）の土曜日に京都へ行きました。","fullSentence":"先週の土曜日に京都へ行きました。","translation":"Thứ bảy tuần trước tôi đã đi Kyoto.","options":["今週","来週","先週","毎週"],"correctIndex":2,"explanation":"「先週」（せんしゅう） nghĩa là tuần trước."},{"id":"cloze_minna_5_22","vocabId":"minna_5_22","targetWord":"今週","targetReading":"こんしゅう","sentence":"（　　）の日曜日は忙しいです。","fullSentence":"今週の日曜日は忙しいです。","translation":"Chủ nhật tuần này tôi rất bận.","options":["先週","今週","来週","去年"],"correctIndex":1,"explanation":"「今週」（こんしゅう） nghĩa là tuần này."},{"id":"cloze_minna_5_23","vocabId":"minna_5_23","targetWord":"来週","targetReading":"らいしゅう","sentence":"（　　）の月曜日にテストがあります。","fullSentence":"来週の月曜日にテストがあります。","translation":"Thứ hai tuần sau sẽ có bài kiểm tra.","options":["先週","今週","来週","おととい"],"correctIndex":2,"explanation":"「来週」（らいしゅう） nghĩa là tuần sau."},{"id":"cloze_minna_5_24","vocabId":"minna_5_24","targetWord":"先月","targetReading":"せんげつ","sentence":"（　　）日本へ来ました。","fullSentence":"先月日本へ来ました。","translation":"Tháng trước tôi đã đến Nhật Bản.","options":["今月","来月","先月","毎月"],"correctIndex":2,"explanation":"「先月」（せんげつ） nghĩa là tháng trước."},{"id":"cloze_minna_5_25","vocabId":"minna_5_25","targetWord":"今月","targetReading":"こんげつ","sentence":"（　　）の終わりにお祭りがあります。","fullSentence":"今月の終わりにお祭りがあります。","translation":"Cuối tháng này sẽ có lễ hội.","options":["先月","今月","来月","去年"],"correctIndex":1,"explanation":"「今月」（こんげつ） nghĩa là tháng này."},{"id":"cloze_minna_5_26","vocabId":"minna_5_26","targetWord":"来月","targetReading":"らいげつ","sentence":"（　　）国へ帰ります。とても楽しみです。","fullSentence":"来月国へ帰ります。とても楽しみです。","translation":"Tháng sau tôi sẽ về nước. Rất là mong chờ.","options":["先月","今月","来月","おととい"],"correctIndex":2,"explanation":"「来月」（らいげつ） nghĩa là tháng sau."},{"id":"cloze_minna_5_27","vocabId":"minna_5_27","targetWord":"去年","targetReading":"きょねん","sentence":"（　　）高校を卒業しました。","fullSentence":"去年高校を卒業しました。","translation":"Năm ngoái tôi đã tốt nghiệp cấp 3.","options":["ことし","来年","去年","先週"],"correctIndex":2,"explanation":"「去年」（きょねん） nghĩa là năm ngoái."},{"id":"cloze_minna_5_28","vocabId":"minna_5_28","targetWord":"ことし","targetReading":"ことし","sentence":"（　　）20歳になりました。","fullSentence":"ことし20歳になりました。","translation":"Năm nay tôi tròn 20 tuổi.","options":["去年","ことし","来年","おととい"],"correctIndex":1,"explanation":"「ことし」（今年） nghĩa là năm nay."},{"id":"cloze_minna_5_29","vocabId":"minna_5_29","targetWord":"来年","targetReading":"らいねん","sentence":"（　　）大学に入ります。","fullSentence":"来年大学に入ります。","translation":"Năm sau tôi sẽ vào đại học.","options":["去年","ことし","来年","先月"],"correctIndex":2,"explanation":"「来年」（らいねん） nghĩa là năm sau."},{"id":"cloze_minna_5_30","vocabId":"minna_5_30","targetWord":"～月","targetReading":"～がつ","sentence":"桜は4（　　）に咲きます。","fullSentence":"桜は4月に咲きます。","translation":"Hoa anh đào nở vào tháng 4.","options":["月","日","年","時"],"correctIndex":0,"explanation":"Số đếm + 「月」（がつ） dùng để chỉ các tháng trong năm."},{"id":"cloze_minna_5_31","vocabId":"minna_5_31","targetWord":"何月","targetReading":"なんがつ","sentence":"誕生日は（　　）ですか。…7月です。","fullSentence":"誕生日は何月ですか。…7月です。","translation":"Sinh nhật bạn là tháng mấy? ...Là tháng 7.","options":["何日","何月","何時","何年"],"correctIndex":1,"explanation":"「何月」（なんがつ） dùng để hỏi tháng mấy."},{"id":"cloze_minna_5_32","vocabId":"minna_5_32","targetWord":"一日","targetReading":"ついたち","sentence":"1月（　　）はお正月です。","fullSentence":"1月一日はお正月です。","translation":"Ngày mùng 1 tháng 1 là ngày tết.","options":["一日","二日","三日","四日"],"correctIndex":0,"explanation":"「一日」（ついたち） là cách đọc đặc biệt của ngày mùng 1 đầu tháng."},{"id":"cloze_minna_5_33","vocabId":"minna_5_33","targetWord":"二日","targetReading":"ふつか","sentence":"5月（　　）に東京へ行きます。","fullSentence":"5月二日に東京へ行きます。","translation":"Tôi sẽ đi Tokyo vào ngày mùng 2 tháng 5.","options":["一日","二日","三日","四日"],"correctIndex":1,"explanation":"「二日」（ふつか） nghĩa là ngày mùng 2 (hoặc khoảng thời gian 2 ngày)."},{"id":"cloze_minna_5_34","vocabId":"minna_5_34","targetWord":"三日","targetReading":"みっか","sentence":"3月（　　）はひな祭りです。","fullSentence":"3月三日はひな祭りです。","translation":"Ngày mùng 3 tháng 3 là lễ hội búp bê Hina Matsuri.","options":["二日","三日","四日","五日"],"correctIndex":1,"explanation":"「三日」（みっか） nghĩa là ngày mùng 3 (hoặc 3 ngày)."},{"id":"cloze_minna_5_35","vocabId":"minna_5_35","targetWord":"四日","targetReading":"よっか","sentence":"5月（　　）はみどりの日です。","fullSentence":"5月四日はみどりの日です。","translation":"Ngày mùng 4 tháng 5 là Ngày Cây xanh ở Nhật Bản.","options":["三日","四日","五日","六日"],"correctIndex":1,"explanation":"「四日」（よっか） nghĩa là ngày mùng 4 (hoặc 4 ngày)."},{"id":"cloze_minna_5_36","vocabId":"minna_5_36","targetWord":"五日","targetReading":"いつか","sentence":"5月（　　）はこどもの日です。","fullSentence":"5月五日はこどもの日です。","translation":"Ngày mùng 5 tháng 5 là Ngày Thiếu nhi.","options":["四日","五日","六日","七日"],"correctIndex":1,"explanation":"「五日」（いつか） nghĩa là ngày mùng 5 (hoặc 5 ngày)."},{"id":"cloze_minna_5_37","vocabId":"minna_5_37","targetWord":"六日","targetReading":"むいか","sentence":"夏休みは8月（　　）からです。","fullSentence":"夏休みは8月六日からです。","translation":"Kỳ nghỉ hè bắt đầu từ ngày mùng 6 tháng 8.","options":["五日","六日","七日","八日"],"correctIndex":1,"explanation":"「六日」（むいか） nghĩa là ngày mùng 6 (hoặc 6 ngày)."},{"id":"cloze_minna_5_38","vocabId":"minna_5_38","targetWord":"七日","targetReading":"なのか","sentence":"7月（　　）は七夕（たなばた）です。","fullSentence":"7月七日は七夕（たなばた）です。","translation":"Ngày mùng 7 tháng 7 là lễ hội Ngưu Lang Chức Nữ Tanabata.","options":["六日","七日","八日","九日"],"correctIndex":1,"explanation":"「七日」（なのか） nghĩa là ngày mùng 7 (hoặc 7 ngày)."},{"id":"cloze_minna_5_39","vocabId":"minna_5_39","targetWord":"八日","targetReading":"ようか","sentence":"4月（　　）に入学式があります。","fullSentence":"4月八日に入学式があります。","translation":"Ngày mùng 8 tháng 4 có lễ khai giảng.","options":["七日","八日","九日","十日"],"correctIndex":1,"explanation":"「八日」（ようか） nghĩa là ngày mùng 8 (hoặc 8 ngày)."},{"id":"cloze_minna_5_40","vocabId":"minna_5_40","targetWord":"九日","targetReading":"ここのか","sentence":"旅行は9月（　　）までです。","fullSentence":"旅行は9月九日までです。","translation":"Chuyến du lịch kéo dài đến ngày mùng 9 tháng 9.","options":["八日","九日","十日","一日"],"correctIndex":1,"explanation":"「九日」（ここのか） nghĩa là ngày mùng 9 (hoặc 9 ngày)."},{"id":"cloze_minna_5_41","vocabId":"minna_5_41","targetWord":"十日","targetReading":"とおか","sentence":"10月（　　）に運動会があります。","fullSentence":"10月十日に運動会があります。","translation":"Ngày mùng 10 tháng 10 có hội thao.","options":["九日","十日","十四日","二十日"],"correctIndex":1,"explanation":"「十日」（とおか） nghĩa là ngày mùng 10 (hoặc 10 ngày)."},{"id":"cloze_minna_5_42","vocabId":"minna_5_42","targetWord":"十四日","targetReading":"じゅうよっか","sentence":"2月（　　）はバレンタインデーです。","fullSentence":"2月十四日はバレンタインデーです。","translation":"Ngày 14 tháng 2 là ngày lễ tình nhân Valentine.","options":["十日","十四日","二十四日","四日"],"correctIndex":1,"explanation":"「十四日」（じゅうよっか） là cách đọc đặc biệt của ngày 14."},{"id":"cloze_minna_5_43","vocabId":"minna_5_43","targetWord":"二十日","targetReading":"はつか","sentence":"給料日は毎月（　　）です。","fullSentence":"給料日は毎月二十日です。","translation":"Ngày trả lương là ngày 20 hàng tháng.","options":["十日","十四日","二十日","二十四日"],"correctIndex":2,"explanation":"「二十日」（はつか） là cách đọc đặc biệt của ngày 20."},{"id":"cloze_minna_5_44","vocabId":"minna_5_44","targetWord":"二十四日","targetReading":"にじゅうよっか","sentence":"12月（　　）はクリスマスイブです。","fullSentence":"12月二十四日はクリスマスイブです。","translation":"Ngày 24 tháng 12 là đêm Giáng sinh.","options":["十四日","二十日","二十四日","四日"],"correctIndex":2,"explanation":"「二十四日」（にじゅうよっか） là cách đọc đặc biệt của ngày 24."},{"id":"cloze_minna_5_45","vocabId":"minna_5_45","targetWord":"～日","targetReading":"～にち","sentence":"テストは25（　　）にあります。","fullSentence":"テストは25日にあります。","translation":"Bài kiểm tra diễn ra vào ngày 25.","options":["日","月","年","時"],"correctIndex":0,"explanation":"Số đếm + 「日」（にち） dùng để chỉ ngày trong tháng."},{"id":"cloze_minna_5_46","vocabId":"minna_5_46","targetWord":"何日","targetReading":"なんにち","sentence":"きょうは（　　）ですか。…15日です。","fullSentence":"きょうは何日ですか。…15日です。","translation":"Hôm nay là ngày mùng mấy? ...Là ngày 15.","options":["何月","何日","何曜日","何時"],"correctIndex":1,"explanation":"「何日」（なんにち） dùng để hỏi ngày trong tháng (ngày mấy)."},{"id":"cloze_minna_5_47","vocabId":"minna_5_47","targetWord":"いつ","targetReading":"いつ","sentence":"国へ帰りますか。…来週（　　）帰りますか。","fullSentence":"いつ国へ帰りますか。…来週帰ります。","translation":"Khi nào bạn về nước? ...Tuần sau tôi sẽ về.","options":["だれ","どこ","いつ","なんにち"],"correctIndex":2,"explanation":"「いつ」 là từ để hỏi thời điểm (khi nào, bao giờ)."},{"id":"cloze_minna_5_48","vocabId":"minna_5_48","targetWord":"誕生日","targetReading":"たんじょうび","sentence":"（　　）おめでとうございます！","fullSentence":"誕生日おめでとうございます！","translation":"Chúc mừng sinh nhật!","options":["誕生日","何曜日","学校","休み"],"correctIndex":0,"explanation":"「誕生日」（たんじょうび） nghĩa là ngày sinh nhật."},{"id":"cloze_minna_5_49","vocabId":"minna_5_49","targetWord":"普通","targetReading":"ふつう","sentence":"（　　）電車は各駅に止まります。","fullSentence":"普通電車は各駅に止まります。","translation":"Tàu thường dừng ở tất cả các ga.","options":["普通","急行","特急","新幹線"],"correctIndex":0,"explanation":"「普通」（ふつう） nghĩa là tàu thường (đỗ tại mọi ga)."},{"i